<script setup lang="ts">
import {computed,ref,watch,nextTick,onScopeDispose} from 'vue';import {useI18n} from 'vue-i18n';import {communityApi,refreshForumInbox,type ForumPost} from '../api/community';import {forumToken,forumUser} from '../stores/community';import {assetUrl} from '../lib/urls';import stickers from '../../../../services/public-reference/community-content.json';
const props=defineProps<{post:ForumPost;open:boolean}>(),emit=defineEmits<{toggle:[];changed:[];conversation:[id:number];login:[];report:[id:number]}>();const {locale}=useI18n(),zh=computed(()=>locale.value==='zh-CN'),text=(cn:string,en:string)=>zh.value?cn:en;
const items=ref<ForumPost[]>([]),body=ref(''),sticker=ref(''),quote=ref<ForumPost|null>(null),picker=ref(false),busy=ref(false),loading=ref(false),message=ref(''),field=ref<HTMLTextAreaElement|null>(null);let sequence=0,disposed=false;
const stickerFor=(id:string|null)=>stickers.stickers.find(s=>s.id===id);
async function load(){if(!props.open)return;const current=++sequence;loading.value=!items.value.length;try{const value=await communityApi<{items:ForumPost[]}>('posts?parent='+props.post.id);if(!disposed&&current===sequence)items.value=value.items;}catch(error){if(current===sequence)message.value=error instanceof Error?error.message:'Unavailable';}finally{if(current===sequence)loading.value=false;}}
async function send(){if(busy.value||(!body.value.trim()&&!sticker.value))return;busy.value=true;message.value='';try{await communityApi('posts',{parent:props.post.id,replyTo:quote.value?.id,title:('回复 / Reply: '+props.post.title).slice(0,120),body:body.value,sticker:sticker.value||null});body.value='';sticker.value='';quote.value=null;picker.value=false;message.value=text('回复已发送，审核通过后公开。','Reply sent; public after moderation.');await load();emit('changed');await refreshForumInbox();}catch(error){message.value=error instanceof Error?error.message:'Unavailable';}finally{busy.value=false;}}
function reply(post:ForumPost){quote.value=post;void nextTick(()=>field.value?.focus({preventScroll:true}));}
watch(()=>props.open,open=>{if(open)void load();else sequence++;},{immediate:true});watch(forumToken,()=>{sequence++;items.value=[];body.value='';sticker.value='';quote.value=null;message.value='';if(props.open)void load();});
const timer=setInterval(()=>{if(props.open&&document.visibilityState==='visible')void load();},8000);onScopeDispose(()=>{disposed=true;sequence++;clearInterval(timer);});
</script>
<template><div class="forum-inline-replies"><button class="button forum-inline-toggle" :aria-expanded="open" @click="emit('toggle')">{{text('回复','Reply')}} <span>{{post.replies||0}}</span> {{open?'⌃':'⌄'}}</button><section v-if="open" class="forum-inline-panel" :aria-label="text('帖子下方回复','Replies below the post')"><p v-if="loading" role="status" class="caption">{{text('正在加载回复…','Loading replies…')}}</p><article v-for="item in items.slice(-5)" :key="item.id" class="forum-inline-message"><strong>{{item.author}}</strong><blockquote v-if="item.reply_to&&item.reply_to!==post.id">{{item.quote_author}} · {{item.quote_body||text('表情贴纸','Sticker')}}</blockquote><p class="forum-body">{{item.body}}</p><img v-if="stickerFor(item.sticker)" class="forum-sticker small" :src="assetUrl(stickerFor(item.sticker)!.src)" :alt="zh?stickerFor(item.sticker)!.zh:stickerFor(item.sticker)!.en"/><div class="forum-inline-meta"><time :datetime="item.created">{{new Date(item.created).toLocaleString(locale)}}</time><span v-if="item.status!=='published'">{{text('待审核，仅自己可见','Pending; visible only to you')}}</span><button v-if="forumUser&&item.status==='published'" type="button" class="button" @click="reply(item)">{{text('回复此消息','Reply to message')}}</button><button v-if="forumUser" type="button" class="button" @click="emit('report',item.id)">{{text('举报回复','Report reply')}}</button></div></article><p v-if="!loading&&!items.length" class="caption">{{text('还没有回复，来说两句。','No replies yet. Join in.')}}</p><button v-if="items.length>5" class="button" @click="emit('conversation',post.id)">{{text('查看全部回复','See all replies')}} →</button><p v-if="message" class="notice" role="status">{{message}}</p><form v-if="forumUser&&post.status==='published'" class="forum-form forum-inline-form" @submit.prevent="send"><div v-if="quote" class="forum-reply-target"><span>{{text('回复','Reply to')}} {{quote.author}} · {{quote.body.slice(0,60)}}</span><button type="button" @click="quote=null">{{text('取消引用','Cancel quote')}}</button></div><label>{{text('在此帖子下回复','Reply below this post')}}<textarea ref="field" v-model="body" rows="2" maxlength="5000" :required="!sticker" :placeholder="text('分享你的看法…','Share your thoughts…')"/></label><div class="forum-composer-actions"><button type="button" class="button" :aria-expanded="picker" @click="picker=!picker">☺ {{text('表情贴纸','Stickers')}}</button><button v-for="emoji in ['🏁','👍','😂','🔥']" :key="emoji" type="button" class="forum-quick-emoji" :aria-label="emoji" :disabled="body.length+emoji.length>5000" @click="body+=emoji">{{emoji}}</button><button class="button primary" :disabled="busy||(!body.trim()&&!sticker)">{{busy?text('发送中…','Sending…'):text('发送回复','Send reply')}}</button></div><div v-if="picker" class="forum-sticker-grid" data-swipe-ignore><button v-for="item in stickers.stickers" :key="item.id" type="button" :aria-label="zh?item.zh:item.en" :aria-pressed="sticker===item.id" @click="sticker=sticker===item.id?'':item.id"><img :src="assetUrl(item.src)" :alt="zh?item.zh:item.en"/></button></div><p v-if="sticker" class="caption">{{text('已选择：','Selected: ')}}{{zh?stickerFor(sticker)!.zh:stickerFor(sticker)!.en}}</p></form><button v-else-if="!forumUser&&post.status==='published'" class="button" @click="emit('login')">{{text('登录后直接回复','Sign in to reply here')}}</button></section></div></template>
